begin;
create or replace function public.has_role(requested_role text) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profile_roles pr join public.roles r on r.id=pr.role_id join public.profiles p on p.id=pr.profile_id where pr.profile_id=auth.uid() and p.is_active and r.code=requested_role)$$;
create or replace function public.has_any_role(requested_roles text[]) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profile_roles pr join public.roles r on r.id=pr.role_id join public.profiles p on p.id=pr.profile_id where pr.profile_id=auth.uid() and p.is_active and r.code=any(requested_roles))$$;
revoke all on function public.has_role(text) from public;revoke all on function public.has_any_role(text[]) from public;grant execute on function public.has_role(text),public.has_any_role(text[]) to anon,authenticated;
alter table public.profiles enable row level security;alter table public.roles enable row level security;alter table public.profile_roles enable row level security;alter table public.brands enable row level security;alter table public.categories enable row level security;alter table public.products enable row level security;alter table public.product_specifications enable row level security;alter table public.product_status_history enable row level security;alter table public.product_images enable row level security;alter table public.inquiries enable row level security;alter table public.customers enable row level security;alter table public.customer_inquiries enable row level security;alter table public.customer_notes enable row level security;alter table public.tags enable row level security;alter table public.customer_tags enable row level security;alter table public.customer_timeline enable row level security;alter table public.collection_settings enable row level security;alter table public.admin_audit_log enable row level security;alter table public.import_jobs enable row level security;
create policy profiles_self_read on public.profiles for select to authenticated using(id=auth.uid() or public.has_role('super_admin'));
create policy profiles_super_admin_write on public.profiles for all to authenticated using(public.has_role('super_admin')) with check(public.has_role('super_admin'));
create policy roles_admin_read on public.roles for select to authenticated using(public.has_any_role(array['viewer','super_admin']));create policy roles_super_admin_write on public.roles for all to authenticated using(public.has_role('super_admin')) with check(public.has_role('super_admin'));
create policy profile_roles_admin_read on public.profile_roles for select to authenticated using(public.has_any_role(array['viewer','super_admin']));create policy profile_roles_super_admin_write on public.profile_roles for all to authenticated using(public.has_role('super_admin')) with check(public.has_role('super_admin'));
create policy brands_public_read on public.brands for select to anon,authenticated using(is_active or public.has_any_role(array['viewer','catalog_manager','super_admin']));create policy brands_catalog_write on public.brands for all to authenticated using(public.has_any_role(array['catalog_manager','super_admin'])) with check(public.has_any_role(array['catalog_manager','super_admin']));
create policy categories_public_read on public.categories for select to anon,authenticated using(is_active or public.has_any_role(array['viewer','catalog_manager','super_admin']));create policy categories_catalog_write on public.categories for all to authenticated using(public.has_any_role(array['catalog_manager','super_admin'])) with check(public.has_any_role(array['catalog_manager','super_admin']));
create policy products_public_read on public.products for select to anon,authenticated using((status='published' and archived_at is null) or public.has_any_role(array['viewer','catalog_manager','media_manager','super_admin']));create policy products_catalog_write on public.products for all to authenticated using(public.has_any_role(array['catalog_manager','super_admin'])) with check(public.has_any_role(array['catalog_manager','super_admin']));
create policy specs_public_read on public.product_specifications for select to anon,authenticated using(exists(select 1 from public.products p where p.id=product_id and p.status='published' and p.archived_at is null) or public.has_any_role(array['viewer','catalog_manager','super_admin']));create policy specs_catalog_write on public.product_specifications for all to authenticated using(public.has_any_role(array['catalog_manager','super_admin'])) with check(public.has_any_role(array['catalog_manager','super_admin']));
create policy history_admin_read on public.product_status_history for select to authenticated using(public.has_any_role(array['viewer','catalog_manager','super_admin']));create policy history_catalog_insert on public.product_status_history for insert to authenticated with check(public.has_any_role(array['catalog_manager','super_admin']));
create policy images_public_read on public.product_images for select to anon,authenticated using(is_active and (image_role='showroom' or exists(select 1 from public.products p where p.id=product_id and p.status='published' and p.archived_at is null)) or public.has_any_role(array['viewer','catalog_manager','media_manager','super_admin']));create policy images_media_write on public.product_images for all to authenticated using(public.has_any_role(array['media_manager','super_admin'])) with check(public.has_any_role(array['media_manager','super_admin']));
create policy inquiries_public_insert on public.inquiries for insert to anon with check(inquiry_type in ('contact','product_availability') and status='new' and assigned_to is null and archived_at is null);create policy inquiries_crm_access on public.inquiries for all to authenticated using(public.has_any_role(array['viewer','crm_manager','super_admin'])) with check(public.has_any_role(array['crm_manager','super_admin']));
create policy customers_crm_access on public.customers for all to authenticated using(public.has_any_role(array['viewer','crm_manager','super_admin'])) with check(public.has_any_role(array['crm_manager','super_admin']));
create policy customer_inquiries_crm_access on public.customer_inquiries for all to authenticated using(public.has_any_role(array['viewer','crm_manager','super_admin'])) with check(public.has_any_role(array['crm_manager','super_admin']));
create policy customer_notes_crm_access on public.customer_notes for all to authenticated using(public.has_any_role(array['viewer','crm_manager','super_admin'])) with check(public.has_any_role(array['crm_manager','super_admin']));
create policy tags_crm_access on public.tags for all to authenticated using(public.has_any_role(array['viewer','crm_manager','super_admin'])) with check(public.has_any_role(array['crm_manager','super_admin']));
create policy customer_tags_crm_access on public.customer_tags for all to authenticated using(public.has_any_role(array['viewer','crm_manager','super_admin'])) with check(public.has_any_role(array['crm_manager','super_admin']));
create policy timeline_crm_access on public.customer_timeline for all to authenticated using(public.has_any_role(array['viewer','crm_manager','super_admin'])) with check(public.has_any_role(array['crm_manager','super_admin']));
create policy settings_public_read on public.collection_settings for select to anon,authenticated using(true);create policy settings_super_admin_write on public.collection_settings for all to authenticated using(public.has_role('super_admin')) with check(public.has_role('super_admin'));
create policy audit_admin_read on public.admin_audit_log for select to authenticated using(public.has_role('super_admin'));create policy audit_trusted_insert on public.admin_audit_log for insert to authenticated with check(public.has_any_role(array['catalog_manager','media_manager','crm_manager','super_admin']) and actor_id=auth.uid());
create policy imports_super_admin_access on public.import_jobs for all to authenticated using(public.has_role('super_admin')) with check(public.has_role('super_admin'));
create policy product_media_read on storage.objects for select to anon,authenticated using(bucket_id='product-media' and exists(select 1 from public.product_images i where i.storage_bucket=bucket_id and i.storage_path=name and i.is_active));
create policy product_media_admin_write on storage.objects for all to authenticated using(bucket_id='product-media' and public.has_any_role(array['media_manager','super_admin'])) with check(bucket_id='product-media' and public.has_any_role(array['media_manager','super_admin'])));
create policy private_transfer_admin on storage.objects for all to authenticated using(bucket_id in ('admin-imports','admin-exports') and public.has_role('super_admin')) with check(bucket_id in ('admin-imports','admin-exports') and public.has_role('super_admin'));
revoke all on all tables in schema public from anon,authenticated;
grant select on public.brands,public.categories,public.products,public.product_specifications,public.product_images,public.collection_settings to anon;
grant insert on public.inquiries to anon;
grant select,insert,update,delete on public.profiles,public.roles,public.profile_roles,public.brands,public.categories,public.products,public.product_specifications,public.product_status_history,public.product_images,public.inquiries,public.customers,public.customer_inquiries,public.customer_notes,public.tags,public.customer_tags,public.customer_timeline,public.collection_settings,public.admin_audit_log,public.import_jobs to authenticated;
commit;
